const express = require('express');
const fs = require('fs');
const path = require('path');
const { jwtAuth } = require('../auth');
const Build = require('../models/Build');

const router = express.Router();

router.get('/api/builds/:buildId/console-stream', jwtAuth, async (req, res) => {
  const build = await Build.findOne({ _id: req.params.buildId });
  if (!build) return res.status(404).json({ error: 'Build not found' });

  const hasAccess = await build.checkUserHasRepoAccess(req.user.id);
  if (!hasAccess) {
    return res.status(403).json({ error: 'Forbidden: you do not have permission to view this build log' });
  }

  const logPath = path.join('/var/log/ci_builds', `${req.params.buildId}.log`);
  if (!fs.existsSync(logPath)) return res.status(404).json({ error: 'Log not found' });

  res.writeHead(200, {
    'Content-Type': 'text/plain; charset=utf-8',
    'Transfer-Encoding': 'chunked',
    'Cache-Control': 'no-cache',
  });

  const stream = fs.createReadStream(logPath, { highWaterMark: 1024 });
  stream.pipe(res);
});
